"""Configuration loading: config.toml + env overrides.

Everything a user must provide is collected by `anycubic-setup` (see setup.py)
which writes ~/.anycubic-mcp/config.toml. No hardcoded paths beyond that.
"""
from __future__ import annotations

import os
import sys
from pathlib import Path

try:
    import tomllib
except ModuleNotFoundError:  # py<3.11
    import tomli as tomllib  # type: ignore

DEFAULT_DIR = Path(os.environ.get("ANYCUBIC_MCP_HOME", Path.home() / ".anycubic-mcp"))
DEFAULT_CONFIG = DEFAULT_DIR / "config.toml"

EXAMPLE = """\
# ~/.anycubic-mcp/config.toml — generated by `anycubic-setup`
[cloud]
session_token_file = "session_token.txt"   # relative to this dir
# or set ANYCUBIC_TOKEN env directly

[printer]
id = 0                    # numeric printer id (anycubic-setup fills this)

[camera]
enabled = true
kx_cam_exe = ""           # absolute path to built kx_cam.exe (optional if vision disabled)

[vision]
base_url = ""             # OpenAI-compatible endpoint, e.g. http://127.0.0.1:4000
model = ""                # multimodal chat model, e.g. qwen2.5vl / deepseek-vl
api_key = "none"

[queue]
file = "queue.json"       # relative to this dir
"""


def load(config_path: str | Path | None = None) -> dict:
    p = Path(config_path) if config_path else (
        Path(os.environ["ANYCUBIC_MCP_CONFIG"])
        if "ANYCUBIC_MCP_CONFIG" in os.environ else DEFAULT_CONFIG)
    cfg: dict = {}
    if p.exists():
        cfg = tomllib.loads(p.read_text(encoding="utf-8"))
    base = p.parent if p.exists() else DEFAULT_DIR

    def rel(key: str) -> str:
        v = cfg.get(key, "") or ""
        return str(Path(base) / v) if v and not os.path.isabs(v) else v

    out = {
        "config_path": str(p),
        "token": os.environ.get("ANYCUBIC_TOKEN", ""),
        "token_file": rel(cfg.get("cloud", {}).get("session_token_file", "")
                          or "session_token.txt"),
        "printer_id": int(cfg.get("printer", {}).get("id", 0)
                          or os.environ.get("ANYCUBIC_PRINTER_ID", 0)),
        "kx_cam_exe": cfg.get("camera", {}).get("kx_cam_exe", ""),
        "camera_enabled": bool(cfg.get("camera", {}).get("enabled", True)),
        "vision_base_url": (cfg.get("vision", {}).get("base_url", "")
                            or os.environ.get("VISION_BASE_URL", "")),
        "vision_model": (cfg.get("vision", {}).get("model", "")
                         or os.environ.get("VISION_MODEL", "")),
        "vision_api_key": cfg.get("vision", {}).get("api_key", "none"),
        "queue_file": rel(cfg.get("queue", {}).get("file", "") or "queue.json"),
    }
    if not out["token"] and os.path.exists(out["token_file"]):
        out["token"] = Path(out["token_file"]).read_text(encoding="utf-8").strip()
    return out


def write_example(path: Path | None = None):
    p = path or DEFAULT_CONFIG
    p.parent.mkdir(parents=True, exist_ok=True)
    if not p.exists():
        p.write_text(EXAMPLE, encoding="utf-8")
        print(f"wrote {p}", file=sys.stderr)
